// This file is generated by AI.

// 项目打开/关闭控制器。

import { copyDirectory } from './commands/server';
import { fs } from './lib/fs';
import { pushRecentProject } from './lib/settings';
import { toUri } from './lib/uri';
import { lspClient } from './lsp/client';
import { disposeModel } from './lsp/monaco';
import { previewClient } from './preview/client';
import { useAppStore } from './state/store';

/** 读取并打开一个文件为新文档。 */
export async function openFile(path: string): Promise<void> {
  const content = await fs.readText(path);
  const normalized = path.replace(/\\/g, '/');
  const isScene = normalized.includes('/game/scene/');
  const name = normalized.split('/').pop() ?? path;
  useAppStore.getState().openDocument({
    path,
    name,
    uri: toUri(path),
    content,
    dirty: false,
    isScene,
  });
}

/** 销毁当前所有文档对应的 Monaco model。 */
function disposeAllModels(): void {
  for (const doc of useAppStore.getState().documents) {
    disposeModel(doc.path);
  }
}

/** 验证并打开一个 WebGAL 项目目录。 */
export async function openProject(path: string): Promise<void> {
  const gameConfig = await fs.exists(`${path}\\game\\config.txt`);
  const indexHtml = await fs.exists(`${path}\\index.html`);
  const hasGameConfig = gameConfig.exists && !gameConfig.isDirectory;
  const hasIndexHtml = indexHtml.exists && !indexHtml.isDirectory;

  if (!hasGameConfig && !hasIndexHtml) {
    throw new Error('不是有效的 WebGAL 项目 (缺少 game/config.txt 或 index.html)');
  }

  await lspClient.start();

  const store = useAppStore.getState();
  const prev = store.projectPath;
  if (prev && prev !== path) {
    lspClient.changeWorkspaceFolders([path], [prev]);
  } else if (!prev) {
    lspClient.changeWorkspaceFolders([path], []);
  }

  // 关闭旧项目的所有文档与 model
  disposeAllModels();
  store.setProject(path);
  store.updateSettings(pushRecentProject(store.settings, path));
  previewClient.resetSite();
}

/** 关闭当前项目。 */
export function closeProject(): void {
  const store = useAppStore.getState();
  if (store.projectPath) {
    lspClient.changeWorkspaceFolders([], [store.projectPath]);
  }
  disposeAllModels();
  store.setProject(null);
  previewClient.resetSite();
}

// -------- 模板切换 --------

/** 将模板目录复制到项目 game/template (替换原有内容)。 */
export async function applyTemplateToProject(projectPath: string, templatePath: string): Promise<void> {
  const target = `${projectPath.replace(/[\\/]+$/, '')}\\game\\template`;
  await fs.remove(target, true).catch(() => {});
  await copyDirectory(templatePath, target);
}

/** 切换当前项目的模板, 并刷新预览 (整体重挂 iframe, 兼容旧版引擎)。 */
export async function switchTemplate(templateId: string | null, templatePath: string | null): Promise<void> {
  const store = useAppStore.getState();
  const projectPath = store.projectPath;
  if (!projectPath) return;

  if (templatePath) {
    await applyTemplateToProject(projectPath, templatePath);
  } else {
    await fs.remove(`${projectPath}\\game\\template`, true).catch(() => {});
  }

  store.setProjectBinding(projectPath, { templateId: templateId ?? undefined });

  // 通知引擎重拉模板 (新版 V1 引擎支持时无需重启即可生效)
  await previewClient.reloadTemplates();

  // 无论引擎版本, 均强制整体刷新预览 iframe, 保证模板立即生效
  // (旧版引擎对 reload-templates 支持不一致 / 经 service worker 缓存, 必须重挂)
  store.requestPreviewReload();
}
